import unittest
from candidate import filter_by_substring

class TestFilterBySubstring(unittest.TestCase):
    def test_normal_case_with_substring_present(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a'), ['abc', 'bacd', 'array'])

    def test_normal_case_with_substring_absent(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'xyz'), [])

    def test_empty_input_list(self):
        self.assertEqual(filter_by_substring([], 'test'), [])

    def test_empty_substring(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd'], ''), ['abc', 'bacd'])

    def test_substring_at_start(self):
        self.assertEqual(filter_by_substring(['axyz', 'bcd', 'xyz'], 'x'), ['axyz', 'xyz'])

    def test_substring_at_end(self):
        self.assertEqual(filter_by_substring(['abc', 'xyz', 'def'], 'z'), ['xyz'])

    def test_substring_in_middle(self):
        self.assertEqual(filter_by_substring(['axyz', 'bcd', 'xyz'], 'yz'), ['axyz', 'xyz'])

    def test_case_sensitivity(self):
        self.assertEqual(filter_by_substring(['ABC', 'abc', 'AbC'], 'a'), ['abc', 'AbC'])

    def test_substring_with_whitespace(self):
        self.assertEqual(filter_by_substring(['hello world', 'test', 'hello'], ' world'), ['hello world'])

    def test_none_input_list(self):
        with self.assertRaises(TypeError):
            filter_by_substring(None, 'test')

    def test_none_substring(self):
        with self.assertRaises(TypeError):
            filter_by_substring(['abc', 'bacd'], None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            filter_by_substring('not_a_list', 'test')

    def test_non_string_substring(self):
        with self.assertRaises(TypeError):
            filter_by_substring(['abc', 'bacd'], 123)

    def test_substring_longer_than_string(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd'], 'xyz'), [])

    def test_all_strings_contain_substring(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'xyz'], 'a'), ['abc', 'bacd', 'xyz'])

    def test_no_strings_contain_substring(self):
        self.assertEqual(filter_by_substring(['xyz', 'def'], 'abc'), [])

    def test_mixed_case_substring(self):
        self.assertEqual(filter_by_substring(['AbCd', 'aBcD', 'ABCd'], 'aBc'), ['AbCd', 'aBcD', 'ABCd'])
